+  return (
+    <Modal
+      title={user ? `Offboard ${user.email}` : 'Offboard user'}
+      open={user !== null}
+      onCancel={onClose}
+      onOk={receipt ? onClose : onOk}
+      okText={receipt ? 'Done' : 'Offboard'}
+      okButtonProps={{
+        danger: !receipt,
+        disabled: !receipt && !ready,
+        loading: submitting,
+      }}
+      cancelButtonProps={{ style: receipt ? { display: 'none' } : undefined }}
+      destroyOnHidden
+      width={620}
+    >
+      {receipt ? (
+        <Receipt receipt={receipt} />
+      ) : previewError ? (
+        <Alert
+          type="error"
