+        {preview.membership_note}
+      </Typography.Text>
+    </Flex>
+  );
+}
+
+function Receipt({ receipt }: { receipt: OffboardReceipt }) {
+  return (
+    <Flex vertical gap={12}>
+      <Alert type="success" showIcon title={`${receipt.email} has been offboarded`} />
+      <Descriptions size="small" column={1} bordered>
